use super::operation_predicates::Predicate;
use super::shared::{ByteOffset, ObjectGroup, ObjectKind, OperationCode, StageContext};

#[derive(Clone, Copy, PartialEq, Eq)]
struct PhaseCode(u32);
#[derive(Clone, Copy)]
struct OpenArgument(u32);
#[derive(Clone, Copy, PartialEq, Eq)]
struct FrameCategory(u32);
#[repr(u32)]
#[derive(Clone, Copy, PartialEq, Eq)]
enum RuleClass { Standard = 0, VariantOne = 1, VariantTwo = 2, Any = 3 }
struct ObjectRule {
    operation: OperationCode,
    phase: PhaseCode,
    group: ObjectGroup,
    kind: ObjectKind,
    predicate: Predicate,
}
struct ObjectProfile {
    category: FrameCategory,
    class: RuleClass,
    rules: &'static [ObjectRule],
}
struct ObjectGroups {
    first: Option<ObjectGroup>,
    second: Option<ObjectGroup>,
}

unsafe fn classify(context: StageContext) -> RuleClass {
    let frame = unsafe { context.frame() };
    if unsafe { frame.field(ByteOffset(0x78)).word() } != 0 { return RuleClass::Any; }
    let mode = unsafe { frame.field(ByteOffset(0x4b4)).word() };
    if mode == 0x19 { return RuleClass::VariantOne; }
    if unsafe { frame.field(ByteOffset(0x27a8)).word() } == 1 { return RuleClass::VariantOne; }
    if mode == 0x1a { RuleClass::VariantTwo } else { RuleClass::Standard }
}

unsafe fn open(context: StageContext, group: ObjectGroup, kind: ObjectKind, argument: OpenArgument) {
    unsafe { super::buffers::xm1_develop_open_object(context.0, group.0, kind.0 as u32, argument.0) };
}
unsafe fn close(context: StageContext, group: ObjectGroup, kind: ObjectKind) {
    unsafe { super::buffers::xm1_develop_close_object(context.0, group.0, kind.0 as u32) };
}
unsafe fn apply_table(context: StageContext, operation: OperationCode, phase: PhaseCode, argument: OpenArgument) -> bool {
    for profile in PROFILES {
        let category = FrameCategory(unsafe { context.frame().field(ByteOffset(0x78)).word() });
        if category != profile.category { continue; }
        let class = unsafe { classify(context) };
        if class != RuleClass::Any && class != profile.class { continue; }
        for rule in profile.rules {
            if rule.operation.0 != operation.0 || rule.phase != phase { continue; }
            if !unsafe { rule.predicate.accepts(context, rule.group) } { continue; }
            if rule.phase.0 == 0 {
                unsafe { open(context, rule.group, rule.kind, argument) };
            } else {
                unsafe { close(context, rule.group, rule.kind) };
            }
        }
        return true;
    }
    false
}

unsafe fn apply_legacy(context: StageContext, operation: OperationCode, phase: PhaseCode, argument: OpenArgument) {
    let Some(groups) = LEGACY_GROUPS.get(operation.0 as usize) else { return; };
    let Some(first) = groups.first else { return; };
    if phase.0 == 1 {
        unsafe { open(context, first, ObjectKind(0), argument) };
        if let Some(second) = groups.second { unsafe { open(context, second, ObjectKind(0), argument) }; }
    } else {
        unsafe { close(context, first, ObjectKind(0)) };
        if let Some(second) = groups.second { unsafe { close(context, second, ObjectKind(0)) }; }
    }
}

unsafe fn set_objects(context: StageContext, operation: OperationCode, phase: PhaseCode, argument: OpenArgument) {
    if unsafe { apply_table(context, operation, phase, argument) } { return; }
    match operation.0 {
        0 | 1 => if phase.0 == 0 {
            unsafe { open(context, ObjectGroup(0x28), ObjectKind(0), argument) };
        } else { unsafe { close(context, ObjectGroup(0x28), ObjectKind(0)) }; },
        2 => if phase.0 == 0 { unsafe { open(context, ObjectGroup(0x17), ObjectKind(0), argument) }; },
        3 => if phase.0 == 0 {
            unsafe { open(context, ObjectGroup(0x18), ObjectKind(0), argument) };
        } else {
            unsafe { close(context, ObjectGroup(0x16), ObjectKind(0)); close(context, ObjectGroup(0x18), ObjectKind(0)); close(context, ObjectGroup(0x17), ObjectKind(0)); }
        },
        0x0b | 0x0c => if phase.0 == 0 {
            let kind = if operation.0 == 0x0b { ObjectKind(1) } else { ObjectKind(2) };
            unsafe { open(context, ObjectGroup(0x30), kind, argument) };
        } else {
            let kind = if operation.0 == 0x0b { ObjectKind(10) } else { ObjectKind(11) };
            unsafe { close(context, ObjectGroup(0x14), kind) };
        },
        0x10 | 0x11 => if phase.0 == 0 {
            let kind = if operation.0 == 0x10 { ObjectKind(1) } else { ObjectKind(2) };
            unsafe { open(context, ObjectGroup(0x29), kind, argument) };
        } else {
            let kind = if operation.0 == 0x10 { ObjectKind(10) } else { ObjectKind(11) };
            unsafe { close(context, ObjectGroup(0x14), kind) };
            if operation.0 == 0x10 && unsafe { context.frame().field(ByteOffset(0x19b4)).byte() } != 0 {
                unsafe { close(context, ObjectGroup(0x14), ObjectKind(11)) };
            }
        },
        0x12 => if phase.0 == 0 {
            unsafe { open(context, ObjectGroup(0x19), ObjectKind(0), argument); open(context, ObjectGroup(0x28), ObjectKind(0), argument); }
        } else {
            unsafe { close(context, ObjectGroup(0x14), ObjectKind(1)); close(context, ObjectGroup(0x14), ObjectKind(2)); close(context, ObjectGroup(0x28), ObjectKind(0)); }
            if unsafe { super::processing::xm1_develop_capture_option_selection() } == 2 {
                unsafe { close(context, ObjectGroup(0x19), ObjectKind(0)) };
            }
        },
        0x13 | 0x14 => if phase.0 == 0 {
            unsafe { open(context, ObjectGroup(0x23), ObjectKind(0), argument) };
        } else { unsafe { close(context, ObjectGroup(0x23), ObjectKind(0)) }; },
        0x1c => if phase.0 == 0 {
            unsafe { open(context, ObjectGroup(0x25), ObjectKind(5), argument); open(context, ObjectGroup(0x20), ObjectKind(0), argument); }
        } else { unsafe { close(context, ObjectGroup(0x20), ObjectKind(0)) }; },
        0x20 => if phase.0 == 0 { unsafe { open(context, ObjectGroup(0x21), ObjectKind(14), argument) }; },
        0x32 => if phase.0 != 0 {
            unsafe { close(context, ObjectGroup(0x30), ObjectKind(1)); close(context, ObjectGroup(0x30), ObjectKind(2)); close(context, ObjectGroup(0x21), ObjectKind(16)); }
        },
        _ => {},
    }
}

#[no_mangle]
pub unsafe extern "C" fn xm1_develop_object_rule_class(context: *mut u8) -> u32 {
    (unsafe { classify(StageContext(context)) }) as u32
}
#[no_mangle]
pub unsafe extern "C" fn xm1_develop_apply_operation_table(context: *mut u8, operation: u32, phase: u32, argument: u32) -> u32 {
    u32::from(unsafe { apply_table(StageContext(context), OperationCode(operation), PhaseCode(phase), OpenArgument(argument)) })
}
#[no_mangle]
pub unsafe extern "C" fn xm1_develop_operation_object_rule(context: *mut u8, operation: u32, phase: u32, argument: u32) {
    unsafe { apply_legacy(StageContext(context), OperationCode(operation), PhaseCode(phase), OpenArgument(argument)) };
}
#[no_mangle]
pub unsafe extern "C" fn xm1_develop_set_operation_objects(context: *mut u8, operation: u32, phase: u32, argument: u32) {
    unsafe { set_objects(StageContext(context), OperationCode(operation), PhaseCode(phase), OpenArgument(argument)) };
}

